WITH cleaned AS (SELECT *, CONCAT_WS('-', status, account_type) AS status_account_type_key FROM accounts WHERE status = 'FROZEN') SELECT *, RANK() OVER (PARTITION BY status ORDER BY balance DESC NULLS FIRST) AS balance_rank, FIRST_VALUE(status) IGNORE NULLS OVER (PARTITION BY status ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_status FROM cleaned
